<script setup lang="ts">
import { Plus, Pencil, Search, Upload } from 'lucide-vue-next'
import { categories, priceLabel, categoryName, type Product } from '../../shared'
definePageMeta({ layout: 'admin' })
const { data: products, refresh } = await useFetch<Product[]>('/api/admin/products', { headers: adminHeaders() })
const search = ref(''), modal = ref(false), saving = ref(false), uploading = ref(false), error = ref('')
const editId = ref<number | null>(null)
const blank = () => ({ name: '', category: 'mug', description: '', price: 0, stock: 0, image: '', gallery: [] as string[], featured: false, active: true })
const form = reactive(blank())
const filtered = computed(() => (products.value || []).filter(p => p.name.includes(search.value) || categoryName(p.category).includes(search.value)))
function openNew() { editId.value = null; Object.assign(form, blank()); error.value = ''; modal.value = true }
function openEdit(p: Product) { editId.value = p.id; Object.assign(form, { name: p.name, category: p.category, description: p.description, price: p.price, stock: p.stock, image: p.image, gallery: (() => { try { return JSON.parse(p.gallery || '[]') as string[] } catch { return [] } })(), featured: !!p.featured, active: !!p.active }); error.value = ''; modal.value = true }
async function upload(event: Event, extra = false) {
  const files = [...((event.target as HTMLInputElement).files || [])]
  if (!files.length) return
  if (files.some(file => file.size > 5 * 1024 * 1024)) { error.value = 'حجم هر تصویر نباید بیش از ۵ مگابایت باشد.'; return }
  if (extra && files.length + form.gallery.length > 8) { error.value = 'حداکثر ۸ تصویر تکمیلی مجاز است.'; return }
  uploading.value = true; error.value = ''
  try { for (const file of files) { const body = new FormData(); body.append('image', file); const result = await $fetch<{ url: string }>('/api/admin/upload', { method: 'POST', headers: adminHeaders(), body }); if (extra) form.gallery.push(result.url); else form.image = result.url } }
  catch (e: any) { error.value = e?.data?.statusMessage || 'بارگذاری تصویر انجام نشد.' }
  finally { uploading.value = false }
}
async function save() {
  saving.value = true; error.value = ''
  try {
    if (editId.value) await $fetch('/api/admin/products/' + editId.value, { method: 'PUT', headers: adminHeaders(), body: form })
    else await $fetch('/api/admin/products', { method: 'POST', headers: adminHeaders(), body: form })
    modal.value = false; await refresh()
  } catch (e: any) { error.value = e?.data?.statusMessage || 'ذخیره‌سازی انجام نشد.' }
  finally { saving.value = false }
}
useSeoMeta({ title: 'مدیریت محصولات | پیله پاتری', robots: 'noindex' })
</script>
<template><div class="admin-heading"><div><h1 class="admin-title">محصولات</h1><p class="admin-desc">مشخصات، قیمت، موجودی و تصاویر محصولات را مدیریت کنید.</p></div><button class="admin-primary" @click="openNew"><Plus :size="17"/> افزودن محصول</button></div><div class="product-tools"><Search :size="17"/><input v-model="search" placeholder="جست‌وجو در محصولات..." aria-label="جست‌وجوی محصول"/><span>{{ filtered.length }} محصول</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>محصول</th><th>دسته‌بندی</th><th>قیمت</th><th>موجودی</th><th>وضعیت</th><th></th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><div class="table-product"><img :src="p.image" :alt="p.name"/><strong>{{ p.name }}</strong></div></td><td>{{ categoryName(p.category) }}</td><td>{{ priceLabel(p.price) }}</td><td>{{ p.stock }} عدد</td><td><span class="pill" :class="p.active ? '' : 'danger'">{{ p.active ? 'فعال' : 'غیرفعال' }}</span></td><td><button @click="openEdit(p)"><Pencil :size="13"/> ویرایش</button></td></tr></tbody></table><div v-if="!filtered.length" class="admin-empty">محصولی پیدا نشد.</div></div><div v-if="modal" class="admin-modal-backdrop" @click.self="modal=false"><div class="admin-modal"><div class="admin-modal-head"><h2>{{ editId ? 'ویرایش محصول' : 'افزودن محصول تازه' }}</h2><button aria-label="بستن" @click="modal=false">×</button></div><form @submit.prevent="save"><div class="admin-form-grid"><label class="form-field full">نام محصول <input v-model="form.name" required maxlength="120" placeholder="مثلاً ماگ آوید"/></label><label class="form-field">دسته‌بندی <select v-model="form.category"><option v-for="c in categories" :key="c.key" :value="c.key">{{ c.name }}</option></select></label><label class="form-field">قیمت (تومان) <input v-model.number="form.price" required type="number" min="0" step="1"/><small>صفر یعنی استعلام قیمت</small></label><label class="form-field">موجودی <input v-model.number="form.stock" required type="number" min="0" step="1"/></label><div class="form-field"><span>تصویر محصول</span><label class="upload-label"><Upload :size="16"/> {{ uploading ? 'در حال بارگذاری...' : 'انتخاب تصویر (حداکثر ۵ مگابایت)' }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="uploading" @change="upload"/></label></div><div v-if="form.image" class="full image-preview"><img :src="form.image" alt="پیش‌نمایش تصویر محصول"/><small>{{ form.image }}</small></div><div class="form-field full"><span>نماهای بیشتر برای گالری محصول (اختیاری)</span><label class="upload-label"><Upload :size="16"/> {{ uploading ? 'در حال بارگذاری...' : 'انتخاب چند تصویر تکمیلی' }}<input type="file" multiple accept="image/jpeg,image/png,image/webp" :disabled="uploading" @change="upload($event, true)"/></label><div v-if="form.gallery.length" class="gallery-previews"><div v-for="(url,index) in form.gallery" :key="url" class="gallery-preview"><img :src="url" alt="نمای تکمیلی"/><button type="button" :aria-label="'حذف نمای ' + (index+1)" @click="form.gallery.splice(index,1)">×</button></div></div></div><label class="form-field full">توضیحات <textarea v-model="form.description" maxlength="2000" placeholder="درباره‌ی این قطعه بنویسید..."/></label><label class="admin-checkbox"><input v-model="form.featured" type="checkbox"/> نمایش در محصولات منتخب صفحه‌ی اصلی</label><label class="admin-checkbox"><input v-model="form.active" type="checkbox"/> فعال و قابل نمایش در فروشگاه</label></div><p v-if="error" class="error-msg admin-error">{{ error }}</p><div class="admin-modal-actions"><button type="button" class="admin-secondary" @click="modal=false">انصراف</button><button type="submit" class="admin-primary" :disabled="saving || uploading || !form.image">{{ saving ? 'در حال ذخیره...' : 'ذخیره‌ی محصول' }}</button></div></form></div></div></template>
<style scoped>.product-tools{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #e8e9e2;padding:0 15px;margin-bottom:15px;max-width:420px;color:#849182}.product-tools input{height:45px;border:0;outline:0;flex:1;min-width:0;font-size:12px}.product-tools span{white-space:nowrap;font-size:11px}.table-product{display:flex;align-items:center;gap:12px}.table-product img{width:47px;height:47px;object-fit:cover}.admin-table button{display:inline-flex;align-items:center;gap:6px}.upload-label{border:1px dashed #b9c6b4;background:#f8faf7;min-height:47px;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;color:#5b7459;font-size:11px}.upload-label input{display:none}.image-preview{display:flex;align-items:center;gap:12px;color:#919c90;font-size:11px;overflow:hidden}.image-preview img{width:56px;height:56px;object-fit:cover}.image-preview small{overflow:hidden;text-overflow:ellipsis;direction:ltr;white-space:nowrap}.gallery-previews{display:flex;gap:9px;flex-wrap:wrap}.gallery-preview{width:70px;height:70px;position:relative}.gallery-preview img{width:100%;height:100%;object-fit:cover}.gallery-preview button{position:absolute;top:0;left:0;border:0;background:#28333b;color:#fff;width:20px;height:20px;line-height:1}</style>
